/** Dev stand-ins for native action sheets / alerts: styles injected at runtime (dev builds only). */
export const MOCK_SHEET_CSS = '/* Dev stand-ins for native iOS action sheets / alerts (the phone shows the real ones). */\n.mock-native {\n  position: absolute;\n  inset: 0;\n  z-index: 1000;\n  display: flex;\n  align-items: flex-end;\n  justify-content: center;\n  font-family: var(--font);\n}\n\n.mock-native.mock-alert {\n  align-items: center;\n}\n\n.mock-backdrop {\n  position: absolute;\n  inset: 0;\n  background: rgba(0, 0, 0, 0.35);\n  opacity: 0;\n  transition: opacity 250ms ease;\n}\n\n.mock-panel {\n  position: relative;\n  width: 100%;\n  max-width: 420px;\n  padding: 0 8px calc(8px + var(--safe-bottom));\n  transform: translate3d(0, 100%, 0);\n  transition: transform 300ms var(--ease-ios);\n}\n\n.mock-alert .mock-panel {\n  width: 270px;\n  padding: 0;\n  transform: scale(1.12);\n  opacity: 0;\n  transition: transform 250ms var(--ease-ios), opacity 200ms ease;\n}\n\n.mock-native.is-open .mock-backdrop {\n  opacity: 1;\n}\n\n.mock-native.is-open .mock-panel {\n  transform: none;\n  opacity: 1;\n}\n\n.mock-group {\n  overflow: hidden;\n  border-radius: 14px;\n  background: var(--bar-bg);\n  -webkit-backdrop-filter: var(--bar-filter);\n  backdrop-filter: var(--bar-filter);\n  margin-top: 8px;\n}\n\n.mock-head {\n  padding: 14px 16px;\n  text-align: center;\n  border-bottom: var(--hairline) solid var(--separator);\n}\n\n.mock-title {\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--label-2);\n}\n\n.mock-alert .mock-title {\n  font-size: 17px;\n  color: var(--label);\n}\n\n.mock-message {\n  margin-top: 4px;\n  font-size: 13px;\n  color: var(--label-2);\n}\n\n.mock-action {\n  display: block;\n  width: 100%;\n  height: 57px;\n  font-size: 20px;\n  text-align: center;\n  color: var(--tint);\n  border-top: var(--hairline) solid var(--separator);\n}\n\n.mock-alert .mock-action {\n  height: 44px;\n  font-size: 17px;\n}\n\n.mock-action:first-child {\n  border-top: 0;\n}\n\n.mock-head + .mock-action {\n  border-top: 0;\n}\n\n.mock-action:active {\n  background: var(--fill-3);\n}\n\n.mock-action.is-destructive {\n  color: var(--red);\n}\n\n.mock-cancel {\n  font-weight: 600;\n}\n\n.mock-sheet .mock-cancel {\n  background: var(--bg-elevated);\n}\n';
